<style>
.ic-wrap{max-width:68rem;margin:1.5rem auto;padding:0 1rem;color:#1e293b;overflow-wrap:anywhere}.ic-wrap h1{font-size:1.65rem;font-weight:700}.ic-wrap h2{font-size:1.15rem;font-weight:700;margin-bottom:.75rem}.ic-card{background:#fff;border:1px solid #dbe3e9;border-radius:.8rem;padding:1.25rem;margin:1rem 0}.ic-note{padding:1rem;border-inline-start:4px solid #0f766e;background:#f0fdfa;margin:1rem 0}.ic-warning{background:#fffbeb;border-color:#d97706}.ic-error{background:#fff1f2;border-color:#be123c}.ic-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(12rem,1fr));gap:1rem}.ic-grid dt{font-size:.85rem;color:#475569}.ic-grid dd{font-size:1.1rem;font-weight:600}.ic-wrap label{display:block;margin:.9rem 0 .4rem;font-weight:600}.ic-wrap input:not([type=checkbox]),.ic-wrap textarea{display:block;width:100%;border:1px solid #94a3b8;border-radius:.4rem;padding:.65rem;background:white}.ic-wrap textarea{min-height:6rem}.ic-actions{display:flex;align-items:center;flex-wrap:wrap;gap:.85rem;margin-top:1rem}.ic-button{display:inline-block;background:#0f766e;color:white!important;border:0;border-radius:.45rem;padding:.7rem 1rem;font-weight:600;cursor:pointer}.ic-wrap a:not(.ic-button){color:#0f766e;text-decoration:underline}.ic-help{font-size:.9rem;color:#475569;margin-top:.4rem;line-height:1.7}.ic-check{display:flex!important;gap:.65rem;align-items:flex-start;font-weight:400!important;line-height:1.7}.ic-check input{margin-top:.35rem;flex:0 0 auto}.ic-table{width:100%;border-collapse:collapse}.ic-table th,.ic-table td{text-align:start;border-bottom:1px solid #e2e8f0;padding:.7rem .5rem;vertical-align:top}.ic-table th{font-size:.85rem;color:#475569}.ic-scroll{overflow-x:auto}.ic-value{unicode-bidi:isolate;direction:ltr;display:inline-block}.ic-reason{white-space:pre-wrap;line-height:1.8} @media(max-width:480px){.ic-wrap{padding:0 .7rem}.ic-card{padding:.9rem}.ic-actions>*{width:100%;text-align:center}.ic-grid{grid-template-columns:1fr 1fr}.ic-wrap h1{font-size:1.4rem}} @media print{.ic-noprint{display:none!important}.ic-wrap{max-width:none;margin:0;color:#000}.ic-card{break-inside:avoid;border-color:#999}.ic-wrap .ic-note{background:#fff}nav,aside,header,footer{display:none!important}}
</style>
